<main class="write-main"><form method="post" action="<?=e(url('/write/editorial/posts/'.$post['id']))?>" class="editorial-form"><?=csrf_field()?><input type="hidden" name="row_version" value="<?=e(editorial_field($values,'row_version',(string)$rowVersion))?>">
<div class="writer-head"><div><span class="writer-kicker">Public evidence & updates</span><h1><?=e($post['title'])?></h1></div><div class="writer-actions"><a class="wbtn" href="<?=e(url('/write/edit/'.$post['id']))?>">Return to article</a><button class="wbtn" name="action" value="draft">Save private draft</button><button class="wbtn primary" name="action" value="publish">Publish reviewed evidence</button></div></div>
