<p class="notice">These are separate, explicitly public fields. The article’s private source notes and planning notes are never imported. Save keeps this working copy private. Publish releases only these reviewed cards and any meaningful update note. The article must already be publicly available.</p>
<div class="editorial-writer-layout"><section>
<?php for($i=0;$i<$cardCount;$i++):?><?php $card=is_array($cards[$i]??null)?$cards[$i]:[]; ?><fieldset class="panel editorial-card-fields"><legend>Public evidence card <?=$i+1?></legend><p class="help">Leave all text fields empty to omit this card. Save to add another slot, up to 12 cards.</p>
<div class="field"><label for="card-label-<?=$i?>">Label</label><input id="card-label-<?=$i?>" name="evidence[<?=$i?>][label]" maxlength="180" value="<?=e(editorial_field($card,'label'))?>"></div>
<div class="field"><label for="card-basis-<?=$i?>">Basis of this evidence</label><select id="card-basis-<?=$i?>" name="evidence[<?=$i?>][basis]"><option value="">Choose a basis…</option><?php foreach(editorial_evidence_bases() as $key=>$label):?><option value="<?=e($key)?>" <?=editorial_field($card,'basis')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div>
<div class="field"><label for="card-summary-<?=$i?>">Public summary</label><textarea id="card-summary-<?=$i?>" name="evidence[<?=$i?>][summary]" maxlength="3000" rows="4"><?=e(editorial_field($card,'summary'))?></textarea></div>
<div class="field"><label for="card-limitations-<?=$i?>">Limitations / what this does not establish</label><textarea id="card-limitations-<?=$i?>" name="evidence[<?=$i?>][limitations]" maxlength="2000" rows="3"><?=e(editorial_field($card,'limitations'))?></textarea></div>
<div class="field"><label for="card-url-<?=$i?>">Public HTTPS source URL · optional</label><input id="card-url-<?=$i?>" name="evidence[<?=$i?>][url]" type="url" maxlength="2000" value="<?=e(editorial_field($card,'url'))?>"></div>
<div class="field"><label for="card-date-<?=$i?>">Actual observation date · optional</label><input id="card-date-<?=$i?>" name="evidence[<?=$i?>][observed_on]" type="date" value="<?=e(editorial_field($card,'observed_on'))?>"></div>
</fieldset><?php endfor;?></section><aside><section class="panel"><h2>A meaningful change</h2><p>Publish the corrected article body first, then record what changed here. Ordinary saves and typo fixes do not need a new public date.</p><div class="field"><label for="editorial-update-kind">Update type</label><select id="editorial-update-kind" name="update_kind"><?php foreach(['none'=>'No meaningful update note','update'=>'Meaningful update','correction'=>'Correction'] as $key=>$label):?><option value="<?=e($key)?>" <?=editorial_field($values,'update_kind','none')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><div class="field"><label for="editorial-update-note">Public explanation of the change</label><textarea id="editorial-update-note" name="update_note" maxlength="2000" rows="7"><?=e(editorial_field($values,'update_note'))?></textarea><p class="help">Explain the factual correction, new evidence or changed conclusion. Published notes are retained in the public history; a later note can clarify an earlier one.</p></div><label class="editorial-check"><input type="checkbox" name="publish_ack" value="1"><span>I have reviewed these exact cards and any update note and approve them for public release.</span></label></section>
<section class="panel"><h2>Currently public</h2><p><?=count($public['evidence'])?> evidence cards · <?=count($public['updates'])?> meaningful update notes.</p><?php if(journeys_post_is_public($post)):?><a href="<?=e(url('/my-thoughts/'.$post['slug']))?>" target="_blank" rel="noopener noreferrer">Read the public article ↗</a><?php else:?><p>Publication is blocked until the article is public. You can save these notes privately now.</p><?php endif;?><?php if($public['updates']):?><ol><?php foreach($public['updates'] as $update):?><li><strong><?=e(ucfirst($update['update_kind']))?> · <?=e(format_date($update['published_at']))?></strong><p><?=e($update['note'])?></p></li><?php endforeach;?></ol><?php endif;?></section></aside></div>
